/**
 * Returns what "Accueil" shows of the tasks of the caller, in the spaces they see:
 *
 * - `stats`: the tasks assigned to them that are not closed ("Assignées à moi", "tâches
 *   ouvertes"), those of them that are late ("En retard", "à replanifier") or due `today`
 *   ("Aujourd’hui", "échéances du jour"), and the tasks assigned to them of the key `done`
 *   ("Terminées"), subtasks included;
 * - `priorities` ("Mes priorités"): 7 of their tasks that are not closed, by due date, the
 *   tasks without a due date last, then in the order of their creation;
 * - `sprints`: the sprints current on `today` (first day on or before it, last day on or
 *   after it), by last day then in the order of their creation, 10 at most, with the counts
 *   of their tasks ("Sprint 14", "3 – 17 nov.", "Avancement");
 * - `lists` ("Listes"): the first 6 lists, in the order of the sidebar (spaces then lists in
 *   the order of their creation), with the counts of their tasks ("14 ouvertes").
 *
 * Archived tasks and the trash are left out of `stats` and `priorities`, the tasks of an
 * archived list stay; archived lists are left out of `sprints` and `lists`. `today` is the
 * date of the caller, in their time zone. A guest, never assigned, gets zeros, no priorities,
 * and the lists shared with them. The mentions and the activity of the inbox come from
 * another route in a later version. Scope `tasks:read` for a personal API token.
 * @summary Read the task part of "Accueil"
 */
export const GetHomeQueryParams = zod.object({
  "today": zod.iso.date().describe('The date of the caller, in their time zone, which task-service does not know: the late\ntasks, the tasks due that day and the current sprints are counted against it.\n')
})

